package com.example.incidentapp.ui.home;
import android.Manifest; import android.content.pm.PackageManager; import android.os.*; import android.view.*; import androidx.activity.result.ActivityResultLauncher; import androidx.activity.result.contract.ActivityResultContracts; import androidx.annotation.NonNull; import androidx.core.content.ContextCompat; import androidx.fragment.app.Fragment; import androidx.lifecycle.ViewModelProvider; import androidx.navigation.fragment.NavHostFragment; import com.example.incidentapp.R; import com.example.incidentapp.databinding.FragmentHomeBinding; import com.example.incidentapp.model.Incidente; import com.example.incidentapp.notifications.NotificationCenter; import com.example.incidentapp.session.SessionManager; import com.example.incidentapp.util.TecnicoLocationManager; import com.example.incidentapp.viewmodel.HomeViewModel; import com.google.android.material.snackbar.Snackbar; import java.util.*;
public class HomeFragment extends Fragment { private FragmentHomeBinding binding; private HomeViewModel viewModel; private boolean esDesarrollador,esTecnico; private final Handler handler=new Handler(Looper.getMainLooper()); private final Runnable poll=new Runnable(){public void run(){if(isAdded()&&binding!=null&&!esDesarrollador){viewModel.cargarNotificaciones();NotificationCenter.sincronizar(requireContext());handler.postDelayed(this,10000);}}}; private final ActivityResultLauncher<String[]> permisoUbicacion=registerForActivityResult(new ActivityResultContracts.RequestMultiplePermissions(),r->{boolean ok=Boolean.TRUE.equals(r.get(Manifest.permission.ACCESS_FINE_LOCATION))||Boolean.TRUE.equals(r.get(Manifest.permission.ACCESS_COARSE_LOCATION));if(ok)iniciarUbicacion();else if(binding!=null)Snackbar.make(binding.getRoot(),"La ubicación necesita permiso",Snackbar.LENGTH_LONG).show();});
 @Override public View onCreateView(@NonNull LayoutInflater i,ViewGroup c,Bundle s){binding=FragmentHomeBinding.inflate(i,c,false);return binding.getRoot();}
 @Override public void onViewCreated(@NonNull View v,Bundle s){super.onViewCreated(v,s);viewModel=new ViewModelProvider(this).get(HomeViewModel.class);SessionManager se=SessionManager.getInstance();String rol=se.getRol();boolean admin="Administrador".equalsIgnoreCase(rol),sol="Solicitante".equalsIgnoreCase(rol);esTecnico="Tecnico".equalsIgnoreCase(rol);esDesarrollador="Desarrollador".equalsIgnoreCase(rol);binding.tvBienvenida.setText("Bienvenido "+se.getNombre());String lugar=esDesarrollador?(!se.getEmpresa().isEmpty()?se.getEmpresa():"Plataforma IncidentApp"):se.getSucursal();binding.tvUsuario.setText(lugar==null||lugar.trim().isEmpty()?"IncidentApp":lugar);binding.tvRol.setText(rol);binding.tvTituloResumen.setVisibility(esDesarrollador?View.GONE:View.VISIBLE);binding.contenedorResumenIncidentes.setVisibility(esDesarrollador?View.GONE:View.VISIBLE);binding.btnVerIncidentes.setVisibility(esDesarrollador?View.GONE:View.VISIBLE);binding.btnNuevoIncidente.setVisibility(sol?View.VISIBLE:View.GONE);binding.btnVerMapa.setVisibility((esDesarrollador||admin||esTecnico)?View.VISIBLE:View.GONE);binding.btnCompartirUbicacion.setVisibility(esTecnico?View.VISIBLE:View.GONE);binding.btnReportes.setVisibility(admin?View.VISIBLE:View.GONE);binding.btnGestionEmpresas.setVisibility(esDesarrollador?View.VISIBLE:View.GONE);binding.btnRegistrarSucursal.setVisibility(esDesarrollador?View.VISIBLE:View.GONE);binding.btnRegistrarUsuario.setVisibility((esDesarrollador||admin)?View.VISIBLE:View.GONE);binding.btnGestionActivos.setVisibility(admin?View.VISIBLE:View.GONE);binding.btnSolicitudesAnulacion.setVisibility(admin?View.VISIBLE:View.GONE);binding.contenedorNotificaciones.setVisibility(esDesarrollador?View.GONE:View.VISIBLE);if(esDesarrollador){binding.btnVerMapa.setText("Ver todas las sucursales en mapa");binding.btnRegistrarUsuario.setText("Gestionar administradores");}else if(admin){binding.btnVerMapa.setText("Ver sucursales y técnicos en mapa");binding.btnRegistrarUsuario.setText("Gestionar técnicos y solicitantes");}else if(esTecnico)binding.btnVerMapa.setText("Ver sucursal en mapa");actualizarBotonUbicacion();binding.btnVerIncidentes.setOnClickListener(x->nav(R.id.action_homeFragment_to_listaIncidentesFragment));binding.btnNuevoIncidente.setOnClickListener(x->nav(R.id.action_homeFragment_to_nuevoIncidenteFragment));binding.btnVerMapa.setOnClickListener(x->nav(R.id.action_homeFragment_to_mapaFragment));binding.btnGestionEmpresas.setOnClickListener(x->nav(R.id.action_homeFragment_to_gestionEmpresasFragment));binding.btnRegistrarSucursal.setOnClickListener(x->nav(R.id.action_homeFragment_to_registrarSucursalFragment));binding.btnRegistrarUsuario.setOnClickListener(x->nav(R.id.action_homeFragment_to_registrarUsuarioFragment));binding.btnGestionActivos.setOnClickListener(x->nav(R.id.action_homeFragment_to_gestionActivosFragment));binding.btnSolicitudesAnulacion.setOnClickListener(x->nav(R.id.action_homeFragment_to_solicitudesAnulacionFragment));binding.btnNotificaciones.setOnClickListener(x->nav(R.id.action_homeFragment_to_notificacionesFragment));binding.btnReportes.setOnClickListener(x->nav(R.id.action_homeFragment_to_reportesFragment));binding.btnCompartirUbicacion.setOnClickListener(x->alternarUbicacion());binding.btnCerrarSesion.setOnClickListener(x->{if(esTecnico&&TecnicoLocationManager.get(requireContext()).isCompartiendo())TecnicoLocationManager.get(requireContext()).detener(listenerUbicacion());SessionManager.getInstance().cerrarSesion();nav(R.id.action_homeFragment_to_loginFragment);});viewModel.getIncidentes().observe(getViewLifecycleOwner(),this::actualizarResumen);viewModel.getLoading().observe(getViewLifecycleOwner(),l->{if(!esDesarrollador)binding.progressHome.setVisibility(Boolean.TRUE.equals(l)?View.VISIBLE:View.GONE);});viewModel.getNoLeidas().observe(getViewLifecycleOwner(),n->{int z=n==null?0:n;binding.tvBadgeNotificaciones.setText(z>99?"99+":String.valueOf(z));binding.tvBadgeNotificaciones.setVisibility(z>0?View.VISIBLE:View.GONE);});if(!esDesarrollador){viewModel.cargarResumen();viewModel.cargarNotificaciones();}}
 private TecnicoLocationManager.Listener listenerUbicacion(){return new TecnicoLocationManager.Listener(){public void onMensaje(String m){if(binding!=null)Snackbar.make(binding.getRoot(),m,Snackbar.LENGTH_SHORT).show();}public void onEstado(boolean a){if(binding!=null)actualizarBotonUbicacion();}};} private void alternarUbicacion(){TecnicoLocationManager m=TecnicoLocationManager.get(requireContext());if(m.isCompartiendo()){m.detener(listenerUbicacion());return;}if(ContextCompat.checkSelfPermission(requireContext(),Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED&&ContextCompat.checkSelfPermission(requireContext(),Manifest.permission.ACCESS_COARSE_LOCATION)!=PackageManager.PERMISSION_GRANTED){permisoUbicacion.launch(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION});}else iniciarUbicacion();} private void iniciarUbicacion(){TecnicoLocationManager.get(requireContext()).iniciar(listenerUbicacion());} private void actualizarBotonUbicacion(){if(binding!=null&&esTecnico)binding.btnCompartirUbicacion.setText(TecnicoLocationManager.get(requireContext()).isCompartiendo()?"Dejar de compartir ubicación":"Compartir mi ubicación");}
 private void nav(int id){NavHostFragment.findNavController(this).navigate(id);} private void actualizarResumen(List<Incidente> l){int a=0,p=0,r=0;if(l!=null)for(Incidente i:l){if("Abierto".equalsIgnoreCase(i.getEstado()))a++;else if("En proceso".equalsIgnoreCase(i.getEstado()))p++;else if("Resuelto".equalsIgnoreCase(i.getEstado()))r++;}binding.tvCantidadAbiertos.setText(String.valueOf(a));binding.tvCantidadProceso.setText(String.valueOf(p));binding.tvCantidadResueltos.setText(String.valueOf(r));}
 @Override public void onResume(){super.onResume();if(viewModel!=null&&!esDesarrollador){viewModel.cargarResumen();viewModel.cargarNotificaciones();handler.removeCallbacks(poll);handler.post(poll);}actualizarBotonUbicacion();} @Override public void onPause(){super.onPause();handler.removeCallbacks(poll);} @Override public void onDestroyView(){super.onDestroyView();handler.removeCallbacks(poll);binding=null;}
}
